        prompt: 'The Larkspur handbook server returns similarity_score = 1 - distance from a Chroma collection created with no metric. A client keeps chunks above 0.5 and silently drops chunks with a cosine of 0.7. Which change makes the 0.5 cutoff mean a cosine of 0.5?',
